@module keyDispatch  src=keyDispatch.lua  loc=119  mode=namespace  self=keyDispatch

# Invariants & contracts
  @contract  returns early (no dispatch) when state.suppressKbd or not state.acceptCmds  @ 68
  @contract  state.pageSuppressed shrinks the walk to the root keymap only — body-region editors (swing, tuning) suppress page bindings without shadowing globals like playPause/quit  @ 69
  @contract  first-hit wins; false declines, releases the key, and lets the page char queue see it  @ 70
  @contract  while cmgr:isPrefixActive(), digits and '/' are captured (no dispatch); Esc cancels; any other key freezes the prefix and falls through to the keychain walk so commands can consumePrefix()  @ 71
  @contract  a captured '/' also opens the menu  @ 72
  @contract  a captured digit dismisses the top scope, resolving the slash as the bar  @ 73
  @contract  while captureLetter is declared, that sink gets bare/Shift letters, not the keychain  @ 74
  @contract  a captured letter comes back in commandHeld, so note entry re-reading the frame skips it  @ 75
  @contract  both captures take from keyQueue at frameMods, as state.claimant -- see docs/keyQueue.md  @ 76

# Shapes
  @shape  dispatchResult = { consumed: bool, commandHeld: { [imguiKey]=true } } — commandHeld holds keys down AND command-bound for the live chord  @ 67

# Imports
  @const ImGui = 'imgui'  @ 8

# Module-level constants
  @const keyDispatch = {}  @ 10

# Private functions
  @fn isDigitMods(mods)  @ 21-23
      -- Capture digits and '/' into the prefix buffer; Esc cancels. Returns
      -- 'consumed' if a prefix-accumulating key fired this frame; nil otherwise
      -- (so the normal keychain walk proceeds). The prefix is NOT finished here
      -- on fall-through: dispatchKeys calls finishPrefix only at the moment a
      -- bound command is about to fire, so idle frames don't kill the buffer.
      -- In prefix mode, digit keys count even with Ctrl/Super held: holding the
      -- chord open while typing a count is a natural reach, and any Ctrl-N or
      -- Super-N command binding is overridden for the duration of prefix mode.
      -- Shift/Alt still disqualify (Shift-digit emits a different char).
  @fn handlePrefixCapture(cmgr, keyQueue, claimant)  @ 25-50
  @fn handleLetterCapture(cmgr, keyQueue, claimant)  @ 54-65
      -- A scope may declare a letter sink (the lotus menu's walk); a bare letter goes to it, not
      -- the keychain (Shift tolerated). Returns the key taken, since a leaf may close the sink first.

# Public API (keyDispatch.*)
  @api keyDispatch.dispatchKeys(state, cmgr, ctx, keyQueue)  @ 77-117

# Uses (outbound edges)
  @use call    ImGui.GetKeyMods  @ dispatchKeys:90
  @use call    ImGui.IsKeyDown  @ dispatchKeys:97
  @use call    ImGui.IsKeyPressed  @ dispatchKeys:100
  @use require imgui  @ <load>:8

# Calls (intra-file)
  @call handleLetterCapture  @ dispatchKeys:85
  @call handlePrefixCapture  @ dispatchKeys:81
  @call isDigitMods  @ handlePrefixCapture:28

# Unresolved receivers
  @drop cmgr:appendPrefix  @ handlePrefixCapture:31,41
  @drop cmgr:cancelPrefix  @ handlePrefixCapture:47
  @drop cmgr:dismissal  @ handlePrefixCapture:34
  @drop cmgr:finishPrefix  @ dispatchKeys:104
  @drop cmgr:invoke  @ handlePrefixCapture:42 dispatchKeys:106
  @drop cmgr:isPrefixActive  @ handlePrefixCapture:26 dispatchKeys:103
  @drop cmgr:keySpec  @ dispatchKeys:95
  @drop cmgr:keychain  @ dispatchKeys:91
  @drop cmgr:letterCapture  @ handleLetterCapture:55
  @drop cmgr:rootKeymap  @ dispatchKeys:91
  @drop keyQueue:frameMods  @ handlePrefixCapture:27 handleLetterCapture:57
  @drop keyQueue:take  @ handlePrefixCapture:30,39,46 handleLetterCapture:60

# REAPER API surface
  @reaper ImGui_GetBuiltinPath
  @reaper MB

# Fields (r read / w write incl. constructor keys)
  @field r ImGui_GetBuiltinPath  @ 4
  @field r Key_0  @ handlePrefixCapture:30
  @field r Key_A  @ handleLetterCapture:60,61
  @field r Key_Escape  @ handlePrefixCapture:46
  @field r Key_Slash  @ handlePrefixCapture:39
  @field r Mod_Ctrl  @ isDigitMods:22
  @field r Mod_Shift  @ handleLetterCapture:58
  @field r Mod_Super  @ isDigitMods:22
  @field r acceptCmds  @ dispatchKeys:78
  @field r claimant  @ dispatchKeys:81,85
  @field w commandHeld  @ dispatchKeys:79,83,87,109,116
  @field w consumed  @ dispatchKeys:79,83,87,109,116
  @field w dispatchKeys  @ dispatchKeys:77
  @field r pageSuppressed  @ dispatchKeys:91
  @field r path  @ 7
  @field w path  @ 7
  @field r suppressKbd  @ dispatchKeys:78
